#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

bool validate(const char *pw) {
    if (pw == NULL || strlen(pw) < 8) {
        return false;
    }
    bool has_digit = false;
    bool has_upper = false;
    bool has_special = false;
    for (int i = 0; pw[i] != '\0'; i++) {
        if (isdigit((unsigned char)pw[i])) has_digit = true;
        if (isupper((unsigned char)pw[i])) has_upper = true;
        if (pw[i] == '!' || pw[i] == '@' || pw[i] == '#' || pw[i] == '$' || pw[i] == '%') {
            has_special = true;
        }
    }
    return has_digit && has_upper && has_special;
}

